```t
t 1
gate loops
task max_sub_array_sum_repeated(arr: seq, k: int, n: int) returns (r: int)
  requires k >= 0
  requires n >= 0
  requires len(arr) > 0
  ensures r == max_sub_array_sum_repeated_spec(arr, k, n)
spec fun max_sub_array_sum_repeated_spec(arr: seq, k: int, n: int): int
  decreases k + n
= if k == 0 then 0 else if n == 0 then max_sub_array_sum_repeated_spec(arr, k, 0) else if k == 1 then max_sub_array_sum_single(arr) else max_sub_array_sum_repeated_spec(arr, k - 1, n)
spec fun max_sub_array_sum_single(arr: seq): int
  decreases len(arr)
= if len(arr) == 0 then 0 else max_sub_array_sum_single_helper(arr, 0, 0, arr[0])
spec fun max_sub_array_sum_single_helper(arr: seq, i: int, cur: int, best: int): int
  decreases len(arr) - i
= if i >= len(arr) then best else max_sub_array_sum_single_helper(arr, i + 1, if cur + arr[i] > arr[i] then cur + arr[i] else arr[i], if if cur + arr[i] > arr[i] then cur + arr[i] else arr[i] > best then if cur + arr[i] > arr[i] then cur + arr[i] else arr[i] else best)
{
  if k == 0 {
    r := 0;
  } else {
    if n == 0 {
      r := max_sub_array_sum_single(arr);
    } else {
      if k == 1 {
        r := max_sub_array_sum_single(arr);
      } else {
        var total: int := 0;
        var i: int := 0;
        while i < len(arr)
          invariant total == (sum_range(arr, 0, i))
          invariant i >= 0 and i <= len(arr)
          decreases len(arr) - i
        {
          total := total + arr[i];
          i := i + 1;
        }
        var best_single: int := max_sub_array_sum_single(arr);
        var best_wrap: int := 0;
        var best_prefix: int := 0;
        var best_suffix: int := 0;
        var cur_prefix: int := 0;
        var cur_suffix: int := 0;
        var j: int := 0;
        while j < len(arr)
          invariant j >= 0 and j <= len(arr)
          invariant cur_prefix == (sum_range(arr, 0, j))
          invariant best_prefix >= cur_prefix
          decreases len(arr) - j
        {
          cur_prefix := cur_prefix + arr[j];
          if cur_prefix > best_prefix {
            best_prefix := cur_prefix;
          } else {
          }
          j := j + 1;
        }
        var m: int := 0;
        while m < len(arr)
          invariant m >= 0 and m <= len(arr)
          invariant cur_suffix == (sum_range(arr, len(arr) - m, len(arr)))
          invariant best_suffix >= cur_suffix
          decreases len(arr) - m
        {
          cur_suffix := cur_suffix + arr[len(arr) - 1 - m];
          if cur_suffix > best_suffix {
            best_suffix := cur_suffix;
          } else {
          }
          m := m + 1;
        }
        if total > 0 {
          best_wrap := best_prefix + best_suffix + (k - 2) * total;
        } else {
          best_wrap := best_single;
        }
        if best_wrap > best_single {
          r := best_wrap;
        } else {
          r := best_single;
        }
      }
    }
  }
}
```
